buggy.mask_fill_infinite_report_expression:
// Rust numerical probe; harness provides an entrypoint and calls body().

use burn::tensor::{backend::Backend, Tensor};
use burn::tensor::tests::{TensorTestBackend, TestBackend};
use burn::tensor::TensorData;
use burn::ndarray::NdArrayBackend;
use burn::device::Device;

// The probe records the 2x2 output elements and also explicit NaN checks.

fn build_expected_shapes() -> [[f32;2];2] { [[0.0,0.0],[0.0,0.0]] }

fn body() {
    // Use the same backend that the burn-tensor crate test harness uses.
    type B = TestBackend;
    let device = Device::<B>::default();

    let tensor = Tensor::<B, 2>::from_data(
        [[f32::NEG_INFINITY, f32::NEG_INFINITY], [f32::NEG_INFINITY, f32::NEG_INFINITY]],
        &device,
    );
    let mask = TensorData::from([[true, false],[false, true]]);

    let filled = tensor.mask_fill(mask, 10.0f32);

    // Record all four elements.
    let a00 = filled.clone().index([0,0]);
    let a01 = filled.clone().index([0,1]);
    let a10 = filled.clone().index([1,0]);
    let a11 = filled.clone().index([1,1]);

    // Convert to scalars for recording.
    let v00: f32 = a00.into_scalar();
    let v01: f32 = a01.into_scalar();
    let v10: f32 = a10.into_scalar();
    let v11: f32 = a11.into_scalar();

    // NaN flags.
    let n00 = v00.is_nan();
    let n01 = v01.is_nan();
    let n10 = v10.is_nan();
    let n11 = v11.is_nan();

    probe_scalar("out_00", v00);
    probe_scalar("out_01", v01);
    probe_scalar("out_10", v10);
    probe_scalar("out_11", v11);

    probe_bool("nan_00", n00);
    probe_bool("nan_01", n01);
    probe_bool("nan_10", n10);
    probe_bool("nan_11", n11);
}
